import{_ as r,C as s,c as n,o as i,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const x=JSON.parse('{"title":"Tax groups","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/taxes/tax-groups.md","filePath":"master/finance/taxes/tax-groups.md","lastUpdated":1791902625000}'),l={name:"master/finance/taxes/tax-groups.md"};function u(p,a,g,c,h,d){const t=s("ImagePopup");return i(),n("div",null,[a[0]||(a[0]=e('<h1 id="tax-groups" tabindex="-1">Tax groups <a class="header-anchor" href="#tax-groups" aria-label="Permalink to &quot;Tax groups&quot;">​</a></h1><p>A tax group is a heading that collects related taxes. Every tax must belong to one tax group. The group gives the tax a family name, such as <code>VAT</code> or <code>Sales Tax</code>, and can be limited to a country.</p><blockquote><p><strong>In simple words:</strong> A tax group is the folder a tax is filed under.</p></blockquote><h2 id="when-to-use-this-page" tabindex="-1">When to use this page <a class="header-anchor" href="#when-to-use-this-page" aria-label="Permalink to &quot;When to use this page&quot;">​</a></h2><ul><li>You add a tax that does not fit an existing family.</li><li>You work in several countries and want a group per country.</li></ul><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><ul><li>Invoices app: <code>Invoices → Configurations → Tax Groups</code></li><li>Accounting app: <code>Accounting → Configurations → Accounting → Tax Groups</code></li></ul>',7)),o(t,{src:"/images1/finance/tax_groups_list.png",alt:"Tax Groups list showing the sample group Tax 15%"}),a[1]||(a[1]=e('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Company</strong>, <strong>Country</strong>, <strong>Created By</strong>, <strong>Name</strong> and <strong>Preceding Subtotal</strong>. You can group the rows by <strong>Name</strong>, <strong>Company</strong>, <strong>Country</strong> or <strong>Created By</strong>.</p><h2 id="create-a-tax-group" tabindex="-1">Create a tax group <a class="header-anchor" href="#create-a-tax-group" aria-label="Permalink to &quot;Create a tax group&quot;">​</a></h2><ol><li>Open the Tax Groups page.</li><li>Click <strong>New Tax Group</strong>.</li><li>Fill in the fields.</li><li>Click <strong>Create</strong>.</li></ol>',4)),o(t,{src:"/images1/finance/tax_group_form.png",alt:"New Tax Group form with Company My Company, Country India, Name GST"}),a[2]||(a[2]=e('<ul><li><strong><em>Company:</em></strong> The company the group belongs to. It starts as your current company.</li><li><strong><em>Country:</em></strong> Optional. Use it when the group is only for one country.</li><li><strong><em>Name:</em></strong> The family name, such as <code>GST</code>. Required.</li><li><strong><em>Preceding Subtotal:</em></strong> Optional text, such as <code>Untaxed Amount</code>. It is a label that can be shown above the group in a tax summary.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Your sample company has a group named <strong>Tax 15%</strong>. Your first sales tax and purchase tax both use it. When you add an 18 % tax for a new region, create a group <code>GST 18</code> and choose it in the <strong>Tax Group</strong> field of the tax. You can also create it straight from the tax form.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A tax group that has taxes cannot be deleted. Aureus shows &quot;Tax Group could not be deleted&quot;.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./taxes.html">Taxes</a></li><li><a href="./tax-settings.html">Tax settings</a></li><li><a href="./fiscal-positions.html">Fiscal positions</a></li></ul>',6))])}const _=r(l,[["render",u]]);export{x as __pageData,_ as default};
